mapper.select:
SELECT id, device_no AS deviceNo, site_zone AS siteZone
FROM device
WHERE device_no = #{deviceNo}

SELECT curve_type AS curveType, sample_time AS sampleTime, reading_value AS value
FROM curve_reading
WHERE device_id = #{deviceId}
AND sample_time >= #{startUtc}
AND sample_time < #{endUtc}
ORDER BY sample_time, curve_type
